        [global::Microsoft.Azure.PowerShell.Cmdlets.NetworkSecurity.PSArgumentCompleterAttribute("Succeeded", "Failed", "Canceled")]
        string ProvisioningState { get; set; }
        /// <summary>Number of mitigations queued for execution.</summary>
        int QueuedMitigation { get; set; }
        /// <summary>Number of mitigations whose rollback is in progress.</summary>
        int RollbackInProgressMitigation { get; set; }
        /// <summary>Number of protected resources with a current agent assessment.</summary>
        int ScannedProtectedCount { get; set; }
        /// <summary>Number of mitigations that completed successfully.</summary>
        int SucceededMitigation { get; set; }
        /// <summary>Number of findings blocked by agent communication failures.</summary>
        int UnreachableFinding { get; set; }

    }
}